{
  "nl": {
    "issue": [
      {
        "text": "合同生效后，当事人就质量、价款或者报酬、履行地点等内容没有约定或者约定不明确的，应当如何确定（合同漏洞的填补）",
        "rules": [
          "c510-1",
          "c510-2",
          "c511-quality-mandatory",
          "c511-quality-recommended",
          "c511-quality-industry",
          "c511-quality-usual",
          "c511-price-gov",
          "c511-price-market",
          "c511-place-money",
          "c511-place-immovable",
          "c511-place-other",
          "c511-time",
          "c511-time-prep",
          "c511-manner",
          "c511-cost",
          "c511-cost-creditor"
        ]
      },
      {
        "text": "通过互联网等信息网络订立的电子合同，其交付商品或者提供服务的时间如何确定",
        "rules": [
          "c512-goods",
          "c512-service-voucher",
          "c512-service-actual",
          "c512-online",
          "c512-agreed"
        ]
      }
    ],
    "conditions": [
      {
        "text": "合同已生效，且当事人就质量、价款或者报酬、履行地点等内容没有约定或者约定不明确",
        "rules": [
          "c510-1"
        ]
      },
      {
        "text": "当事人不能就上述内容达成补充协议",
        "rules": [
          "c510-2"
        ]
      },
      {
        "text": "依第510条按照合同相关条款或者交易习惯仍不能确定",
        "rules": [
          "c511-quality-mandatory",
          "c511-price-market",
          "c511-place-money",
          "c511-time",
          "c511-manner",
          "c511-cost"
        ]
      },
      {
        "text": "质量要求不明确，且依次存在强制性国家标准、推荐性国家标准、行业标准，或者均无而需按通常标准或符合合同目的的特定标准",
        "rules": [
          "c511-quality-mandatory",
          "c511-quality-recommended",
          "c511-quality-industry",
          "c511-quality-usual"
        ]
      },
      {
        "text": "价款或者报酬不明确",
        "rules": [
          "c511-price-gov",
          "c511-price-market"
        ]
      },
      {
        "text": "履行地点不明确，且标的分别为给付货币、交付不动产、其他标的",
        "rules": [
          "c511-place-money",
          "c511-place-immovable",
          "c511-place-other"
        ]
      },
      {
        "text": "履行期限不明确",
        "rules": [
          "c511-time",
          "c511-time-prep"
        ]
      },
      {
        "text": "履行方式不明确",
        "rules": [
          "c511-manner"
        ]
      },
      {
        "text": "履行费用的负担不明确；或者因债权人原因增加了履行费用",
        "rules": [
          "c511-cost",
          "c511-cost-creditor"
        ]
      },
      {
        "text": "电子合同的标的为交付商品并采用快递物流方式交付",
        "rules": [
          "c512-goods"
        ]
      },
      {
        "text": "电子合同的标的为提供服务，且电子凭证或者实物凭证载明了时间",
        "rules": [
          "c512-service-voucher"
        ]
      },
      {
        "text": "电子合同标的为提供服务，但凭证未载明时间或者载明时间与实际提供服务时间不一致",
        "rules": [
          "c512-service-actual"
        ]
      },
      {
        "text": "电子合同的标的物采用在线传输方式交付，且已进入对方当事人指定的特定系统并能够检索识别",
        "rules": [
          "c512-online"
        ]
      },
      {
        "text": "电子合同当事人对交付商品或者提供服务的方式、时间另有约定",
        "rules": [
          "c512-agreed"
        ]
      }
    ],
    "exceptions": [
      {
        "text": "依法应当执行政府定价或者政府指导价的，依照规定履行，不适用订立合同时履行地的市场价格规则",
        "rules": [
          "c511-price-gov"
        ]
      },
      {
        "text": "因债权人原因增加的履行费用，由债权人负担，不适用由履行义务一方负担的一般规则",
        "rules": [
          "c511-cost-creditor"
        ]
      },
      {
        "text": "电子合同当事人对交付商品或者提供服务的方式、时间另有约定的，按照其约定，不适用第512条第1款、第2款的法定交付时间规则",
        "rules": [
          "c512-agreed"
        ]
      }
    ],
    "effects": [
      {
        "text": "当事人可以就质量、价款或者报酬、履行地点等内容协议补充",
        "rules": [
          "c510-1"
        ]
      },
      {
        "text": "不能达成补充协议的，按照合同相关条款或者交易习惯确定该内容",
        "rules": [
          "c510-2"
        ]
      },
      {
        "text": "质量要求依次按强制性国家标准、推荐性国家标准、行业标准、通常标准或者符合合同目的的特定标准确定",
        "rules": [
          "c511-quality-mandatory",
          "c511-quality-recommended",
          "c511-quality-industry",
          "c511-quality-usual"
        ]
      },
      {
        "text": "价款或者报酬按照订立合同时履行地的市场价格履行；依法应当执行政府定价或者政府指导价的，依照规定履行",
        "rules": [
          "c511-price-gov",
          "c511-price-market"
        ]
      },
      {
        "text": "履行地点：给付货币的，在接受货币一方所在地履行；交付不动产的，在不动产所在地履行；其他标的，在履行义务一方所在地履行",
        "rules": [
          "c511-place-money",
          "c511-place-immovable",
          "c511-place-other"
        ]
      },
      {
        "text": "履行期限不明确的，债务人可以随时履行，债权人也可以随时请求履行",
        "rules": [
          "c511-time"
        ]
      },
      {
        "text": "随时履行或者随时请求履行的，应当给对方必要的准备时间",
        "rules": [
          "c511-time-prep"
        ]
      },
      {
        "text": "履行方式不明确的，按照有利于实现合同目的的方式履行",
        "rules": [
          "c511-manner"
        ]
      },
      {
        "text": "履行费用由履行义务一方负担；因债权人原因增加的履行费用，由债权人负担",
        "rules": [
          "c511-cost",
          "c511-cost-creditor"
        ]
      },
      {
        "text": "电子合同标的为交付商品并采用快递物流方式交付的，收货人的签收时间为交付时间",
        "rules": [
          "c512-goods"
        ]
      },
      {
        "text": "电子合同标的为提供服务的，以凭证载明的时间为提供服务时间；凭证未载明时间或者载明时间与实际不一致的，以实际提供服务的时间为准",
        "rules": [
          "c512-service-voucher",
          "c512-service-actual"
        ]
      },
      {
        "text": "电子合同标的物采用在线传输方式交付的，合同标的物进入对方当事人指定的特定系统且能够检索识别的时间为交付时间",
        "rules": [
          "c512-online"
        ]
      },
      {
        "text": "电子合同当事人对交付商品或者提供服务的方式、时间另有约定的，按照其约定确定交付或者服务时间",
        "rules": [
          "c512-agreed"
        ]
      }
    ],
    "priority": [
      {
        "text": "第510条的协议补充、按照合同相关条款或者交易习惯确定，优先于第511条的法定补充规则（第511条以“依据前条规定仍不能确定”为前提）",
        "rules": [
          "c510-2"
        ]
      },
      {
        "text": "质量标准的适用有先后顺序：强制性国家标准优先于推荐性国家标准，推荐性国家标准优先于行业标准，行业标准优先于通常标准或者符合合同目的的特定标准",
        "rules": [
          "c511-quality-mandatory",
          "c511-quality-recommended",
          "c511-quality-industry",
          "c511-quality-usual"
        ]
      },
      {
        "text": "政府定价或者政府指导价规则优先于订立合同时履行地市场价格规则",
        "rules": [
          "c511-price-gov"
        ]
      },
      {
        "text": "因债权人原因增加的履行费用由债权人负担，优先于由履行义务一方负担的一般规则",
        "rules": [
          "c511-cost-creditor"
        ]
      },
      {
        "text": "电子合同当事人的约定优先于第512条第1款、第2款的法定交付时间规则",
        "rules": [
          "c512-agreed"
        ]
      }
    ],
    "distinguish": [
      {
        "text": "笔记节点（第三编第十四章第四节）只讲全面履行、诚实信用、保护生态环境等履行的一般规则，未涉及第510–512条的漏洞填补与电子合同交付时间；本卡片以法条原文为准",
        "rules": []
      },
      {
        "text": "LEGO卡片把“选择之债的选择权行使与转移”列入本条，但第510、511条未规定选择之债，该内容属学理，未形式化",
        "rules": []
      },
      {
        "text": "LEGO卡片称漏洞填补顺序为“协议补充→合同有关条款/性质/目的/交易习惯→合同编分则→合同编通则”，法条原文只到“合同相关条款或者交易习惯”，参照分则、通则属学理",
        "rules": []
      },
      {
        "text": "LEGO卡片所称“政府定价情形下价格调整以交付时为准、逾期履行按特殊规则执行”属第513条内容，不在本行挂载法条范围内",
        "rules": []
      }
    ]
  },
